// ⌘K search over a small local index (content/search-index.json, generated by `npm run gen:search`).
// Every word of the query must match the start of a word in an entry; titles count most.

export type SearchKind = "page" | "chapter" | "section" | "concept" | "problem" | "question";

export type SearchEntry = {
  kind: SearchKind;
  title: string;
  /** Where it lives, shown under the title ("LLD 28 · Classic builds"). */
  sub: string;
  href: string;
  /** Extra words that should find it (a definition, a problem's shape), matched with less weight. */
  text?: string;
};

export const kindLabel: Record<SearchKind, string> = {
  page: "Pages",
  chapter: "Chapters",
  section: "Sections",
  concept: "Concepts",
  problem: "Problems",
  question: "Top questions",
};

const KIND_WEIGHT: Record<SearchKind, number> = { page: 3, chapter: 3, problem: 2.5, concept: 2, question: 1.5, section: 1 };

export const words = (s: string) =>
  s
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .split(/[^a-z0-9₹]+/)
    .filter(Boolean);

/** Ranks entries for a query; an empty query returns nothing. */
export function search(entries: SearchEntry[], query: string, limit = 24): SearchEntry[] {
  const q = words(query);
  if (!q.length) return [];
  const scored: { e: SearchEntry; score: number }[] = [];
  for (const e of entries) {
    const title = words(e.title);
    const rest = words(`${e.sub} ${e.text ?? ""}`);
    let score = 0;
    let all = true;
    for (const t of q) {
      if (title.includes(t)) score += 4;
      else if (title.some((w) => w.startsWith(t))) score += 3;
      else if (rest.includes(t)) score += 1.5;
      else if (rest.some((w) => w.startsWith(t))) score += 1;
      else {
        all = false;
        break;
      }
    }
    if (!all) continue;
    if (title.join(" ") === q.join(" ")) score += 6;
    else if (title.join(" ").startsWith(q.join(" "))) score += 3;
    scored.push({ e, score: score * KIND_WEIGHT[e.kind] - title.length * 0.05 });
  }
  return scored.sort((a, b) => b.score - a.score).slice(0, limit).map((x) => x.e);
}
